add_action( 'woocommerce_update_product', 'perfectpixel_log_product_update' );

/**
 * Write a line to the "perfectpixel" WooCommerce log. Levels: debug, info, notice, warning, error.
 */
function perfectpixel_log( $message, $level = 'info', $source = 'perfectpixel' ) {
	if ( ! function_exists( 'wc_get_logger' ) ) {
		return;
	}
	if ( ! is_string( $message ) ) {
		$message = wp_json_encode( $message );
	}
	wc_get_logger()->log( $level, $message, array( 'source' => $source ) );
}

// Example: who edited which product.
function perfectpixel_log_product_update( $product_id ) {
	$user = wp_get_current_user();
	perfectpixel_log( sprintf( 'Product #%d updated by %s', $product_id, $user->exists() ? $user->user_login : 'system' ) );
}
